<?php ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PRIMONIZER FOREX AI</title><style>body{margin:0;background:#050a10;color:#eef6ff;font:15px Arial,sans-serif}.wrap{max-width:1250px;margin:auto;padding:18px}.top{display:flex;justify-content:space-between;align-items:center}.brand{font-size:22px;font-weight:900}.brand b{color:#27e0a0}.card{background:#0b1622;border:1px solid #21384e;border-radius:16px;padding:18px;margin-top:16px}.hero,.uploadGrid,.charts,.storygrid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.muted{color:#91a7bb;line-height:1.55}.slot{border:1px dashed #34536d;border-radius:12px;padding:12px;background:#07111b}.slot input,.slot select{width:100%;margin-top:8px;background:#050d15;color:#fff;border:1px solid #29435b;padding:10px;border-radius:8px}.thumb{display:none;width:100%;height:160px;object-fit:contain;margin-top:8px;background:#02060a;cursor:zoom-in}.btn{width:100%;padding:15px;margin-top:14px;border:0;border-radius:10px;background:#27e0a0;color:#03120d;font-weight:900;cursor:pointer}.btn:disabled{opacity:.5}.result{display:none}.chartCard{background:#02070d;border:1px solid #29435b;border-radius:12px;overflow:hidden}.chartHead,.info{padding:12px;background:#091521}.chartImg{width:100%;display:block;cursor:zoom-in}.ob{border-left:4px solid #27e0a0;padding:10px;background:#061a14}.entry{border-left:4px solid #ffd166;padding:10px;background:#1d1805;margin-top:8px}.final{font-size:19px;font-weight:900;white-space:pre-line;line-height:1.6}.error{color:#ff6378;margin-top:10px}.modal{display:none;position:fixed;z-index:99;inset:0;background:#000e;align-items:center;justify-content:center;padding:15px}.modal.open{display:flex}.modal img{max-width:96vw;max-height:92vh}.close{position:fixed;right:20px;top:10px;font-size:35px;cursor:pointer}@media(max-width:850px){.hero,.uploadGrid,.charts,.storygrid{grid-template-columns:1fr}.wrap{padding:10px}}</style></head><body><div class="wrap"><div class="top"><div class="brand">PRIMONIZER <b>FOREX AI</b></div><div>● MULTI-TIMEFRAME TUTOR</div></div><div class="hero"><div class="card"><h1>Upload 1–4 timeframes</h1><p class="muted">Choose each chart separately. Images are compressed in your browser before upload so InfinityFree does not reject large screenshots.</p><form id="form"><label>SYMBOL</label><select name="symbol" style="width:100%;background:#050d15;color:white;padding:11px;border:1px solid #29435b;border-radius:8px"><option>XAUUSD</option><option>EURUSD</option><option>GBPUSD</option><option>USDJPY</option><option>BTCUSD</option><option>V75</option><option>OTHER</option></select><div class="uploadGrid" id="slots"></div><button class="btn" id="go">ANALYZE ALL TIMEFRAMES</button><div id="err" class="error"></div></form></div><div class="card"><h2>Visual-first result</h2><p class="muted">The final picture contains the important information directly on the chart: structure, liquidity, valid OB, FVG, entry/watch, invalidation and target. Click it for full-size preview.</p><div class="final">HIGH TF → STRUCTURE → LIQUIDITY → OB/FVG → LOW TF CONFIRMATION → ENTRY → TARGET</div></div></div><section id="result" class="result"><div class="card"><h2 id="title"></h2><div id="final" class="final"></div><p id="reason" class="muted"></p></div><div id="charts" class="charts"></div><div class="card"><h2>Market story</h2><div id="story" class="storygrid"></div></div></section></div><div id="modal" class="modal"><span class="close" id="close">×</span><img id="big"></div><script>
const slots=document.getElementById('slots');for(let i=0;i<4;i++){const s=document.createElement('div');s.className='slot';s.innerHTML='<b>CHART '+(i+1)+'</b><select class="tf"><option>H4</option><option>H1</option><option>M30</option><option>M15</option><option>M5</option><option>M1</option><option>D1</option><option>UNKNOWN</option></select><input class="file" type="file" accept="image/png,image/jpeg,image/webp"><img class="thumb"><small class="size" style="display:block;color:#71869a;margin-top:6px"></small>';slots.appendChild(s);const f=s.querySelector('.file'),im=s.querySelector('.thumb'),sz=s.querySelector('.size');f.addEventListener('change',()=>{if(f.files&&f.files[0]){im.src=URL.createObjectURL(f.files[0]);im.style.display='block';sz.textContent='Selected: '+(f.files[0].size/1048576).toFixed(2)+' MB'}})}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function openBig(src){document.getElementById('big').src=src;document.getElementById('modal').classList.add('open')}document.getElementById('close').onclick=()=>document.getElementById('modal').classList.remove('open');document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')e.currentTarget.classList.remove('open')};
function compress(file){return new Promise((resolve,reject)=>{const im=new Image();const u=URL.createObjectURL(file);im.onload=()=>{let w=im.naturalWidth,h=im.naturalHeight,m=Math.max(w,h);if(m>1600){w=Math.round(w*1600/m);h=Math.round(h*1600/m)}const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);c.toBlob(b=>{URL.revokeObjectURL(u);if(!b)return reject(new Error('Could not prepare image'));resolve(new File([b],'chart.jpg',{type:'image/jpeg'}))},'image/jpeg',.78)};im.onerror=()=>reject(new Error('Could not read image'));im.src=u})}
function annotate(src,a){return new Promise(resolve=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas'),w=Math.min(1500,im.naturalWidth),h=Math.round(im.naturalHeight*(w/im.naturalWidth));c.width=w;c.height=h;const x=c.getContext('2d');x.drawImage(im,0,0,w,h);x.font='bold '+Math.max(12,w/75)+'px Arial';(a.annotations||[]).forEach(o=>{let X=(+o.x||0)*w,Y=(+o.y||0)*h,C=o.type==='FVG'?'#55a9ff':o.type&&o.type.includes('BEAR')?'#ff6378':o.type&&o.type.includes('BULL')?'#27e0a0':o.type==='LIQUIDITY'||o.type==='SWEEP'?'#ffd166':'#fff';x.strokeStyle=C;x.fillStyle=C;x.lineWidth=3;if(o.x2!=null){let X2=(+o.x2||0)*w,Y2=(+o.y2||0)*h;x.globalAlpha=.16;x.fillRect(Math.min(X,X2),Math.min(Y,Y2),Math.abs(X2-X),Math.abs(Y2-Y));x.globalAlpha=1;x.strokeRect(Math.min(X,X2),Math.min(Y,Y2),Math.abs(X2-X),Math.abs(Y2-Y))}else{x.beginPath();x.arc(X,Y,7,0,Math.PI*2);x.fill()}x.fillText(o.label||o.type,Math.min(w-180,Math.max(4,X+8)),Math.max(16,Y-8))});let p=a.path||[];if(p.length>1){x.strokeStyle=a.direction==='BEARISH'?'#ff6378':a.direction==='BULLISH'?'#27e0a0':'#ffd166';x.lineWidth=5;x.setLineDash([12,8]);x.beginPath();p.forEach((q,i)=>i?x.lineTo(q.x*w,q.y*h):x.moveTo(q.x*w,q.y*h));x.stroke();x.setLineDash([])}resolve(c.toDataURL('image/jpeg',.88))};im.src=src})}
async function render(d,compressed){document.getElementById('result').style.display='block';const o=d.analysis?.overall||{};document.getElementById('title').textContent=(o.direction||'NEUTRAL')+' • '+(o.next_move||'WAIT');document.getElementById('final').textContent=(o.entry_plan||'WAIT FOR CONFIRMATION')+'\nInvalidation: '+(o.invalidation||'not defined')+'\nTargets: '+(o.targets||'not defined');document.getElementById('reason').textContent=o.reason||'';document.getElementById('story').innerHTML=(o.market_story||[]).map((x,i)=>'<div class="panel"><b>STEP '+(i+1)+'</b><br>'+esc(x)+'</div>').join('');const out=document.getElementById('charts');out.innerHTML='';for(let i=0;i<compressed.length;i++){const src=URL.createObjectURL(compressed[i]),q=d.analysis.charts[i]||{},img=await annotate(src,q),card=document.createElement('div');card.className='chartCard';card.innerHTML='<div class="chartHead"><b>'+esc(q.timeframe||'CHART '+(i+1))+'</b> '+esc(q.direction||'NEUTRAL')+'</div>';const pic=document.createElement('img');pic.className='chartImg';pic.src=img;pic.onclick=()=>openBig(img);card.appendChild(pic);const ob=q.valid_order_block||{};const inf=document.createElement('div');inf.className='info';inf.innerHTML='<div class="ob"><b>VALID ORDER BLOCK: '+esc(ob.status||'NONE')+'</b><br>'+esc(ob.why||'No reliable candidate.')+'<br><small>Why not others: '+esc(ob.why_not_others||'Insufficient evidence')+'</small></div><div class="entry"><b>ENTRY / WATCH</b><br>'+esc(q.entry?.zone||'Not clearly visible')+'<br><small>Trigger: '+esc(q.entry?.confirmation||'Wait for confirmation')+'<br>Invalidation: '+esc(q.entry?.invalidation||'Not defined')+'<br>Target: '+esc(q.entry?.target||'Not defined')+'</small></div>';card.appendChild(inf);out.appendChild(card)}}
document.getElementById('form').onsubmit=async e=>{e.preventDefault();const err=document.getElementById('err'),btn=document.getElementById('go'),ins=[...document.querySelectorAll('.file')],ts=[...document.querySelectorAll('.tf')],fd=new FormData(),compressed=[];err.textContent='';for(let i=0;i<ins.length;i++){if(ins[i].files[0]){btn.textContent='PREPARING '+(i+1)+'/4...';const f=await compress(ins[i].files[0]);compressed.push(f);fd.append('charts[]',f);fd.append('timeframes[]',ts[i].value)}}if(!compressed.length){err.textContent='Choose at least one image first.';return}fd.append('symbol',document.querySelector('[name=symbol]').value);btn.disabled=true;btn.textContent='ANALYZING ALL TIMEFRAMES...';try{const r=await fetch('analyze.php',{method:'POST',body:fd});const text=await r.text();let d;try{d=JSON.parse(text)}catch(e){throw new Error('Server returned non-JSON. '+text.slice(0,700))}if(!r.ok||d.error)throw new Error(d.error||'Analysis failed');await render(d,compressed)}catch(e){err.textContent=e.message}finally{btn.disabled=false;btn.textContent='ANALYZE ALL TIMEFRAMES'}};</script></body></html>